def num_islands(g):
    seen = set()
    def dfs(r, c):
        if (r, c) in seen or not (0 <= r < len(g) and 0 <= c < len(g[0])) or g[r][c] == '0':
            return
        seen.add((r, c))
        for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
            dfs(r + dr, c + dc)
    count = 0
    for r in range(len(g)):
        for c in range(len(g[0])):
            if g[r][c] == '1' and (r, c) not in seen:
                dfs(r, c); count += 1
    return count
